head.b:skin:
/*
 * UltraPress Blogger Theme
 * Version: 2.5.0 (High Speed, SEO & AdSense Optimized)
 * Author: UltraPress Studio
 * License: Open Source (MIT)
 */

:root {
  --font-main: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --color-primary: #0f766e;
  --color-primary-hover: #0d635c;
  --color-accent: #2563eb;

  --bg-page: #f8fafc;
  --bg-surface: #ffffff;
  --bg-subtle: #f1f5f9;
  --border-color: #e2e8f0;
  --border-subtle: #edf2f7;

  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-light: #94a3b8;

  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.08), 0 2px 4px -2px rgb(0 0 0 / 0.05);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.08);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --container-max: 1200px;
  --header-height: 64px;
}

[data-theme='dark'] {
  --bg-page: #0b0f17;
  --bg-surface: #111827;
  --bg-subtle: #1e293b;
  --border-color: #1f2937;
  --border-subtle: #2d3748;

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-light: #64748b;

  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.5);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.4);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.4);
}

/* CSS Reset & Foundation */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-family: var(--font-main);
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.6;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.15s ease;
}

a:hover {
  color: var(--color-primary);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Reading Progress Bar */
#reading-progress {
  position: fixed;
  top: 0;
  left: 0;
  height: 3px;
  width: 0%;
  background-color: var(--color-primary);
  z-index: 9999;
  transition: width 0.1s ease-out;
}

/* Top Navigation Bar */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
  backdrop-filter: blur(8px);
  height: var(--header-height);
}

.header-container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 1.25rem;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.brand-zone {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 800;
  font-size: 1.25rem;
  letter-spacing: -0.02em;
  color: var(--text-main);
  white-space: nowrap;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-muted);
}

.nav-links a:hover {
  color: var(--text-main);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.btn-icon {
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-icon:hover {
  background-color: var(--bg-subtle);
  color: var(--text-main);
  border-color: var(--text-muted);
}

.hamburger-btn {
  display: none;
}

/* Mobile Nav Drawer */
.mobile-drawer {
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.6);
  z-index: 200;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s ease, visibility 0.2s ease;
}

.mobile-drawer.active {
  opacity: 1;
  visibility: visible;
}

.drawer-content {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  width: 280px;
  background-color: var(--bg-surface);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  transform: translateX(-100%);
  transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.mobile-drawer.active .drawer-content {
  transform: translateX(0);
}

.drawer-links {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  font-size: 1rem;
  font-weight: 600;
}

/* Main Layout Grid */
.main-wrapper {
  max-width: var(--container-max);
  margin: 1.5rem auto 3rem;
  padding: 0 1.25rem;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 2rem;
  align-items: start;
}

/* AdSense Containers (Fully Policy Compliant) */
.ad-slot-wrapper {
  margin: 1.5rem 0;
  text-align: center;
  background-color: var(--bg-surface);
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.75rem 0.5rem;
  overflow: hidden;
}

.ad-label {
  display: block;
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.ad-slot-header {
  max-width: 728px;
  margin: 1rem auto;
}

.ad-slot-inarticle {
  margin: 2rem 0;
}

.ad-slot-sidebar {
  margin-bottom: 1.5rem;
}

/* Blog Post List & Cards (Homepage / Archives) */
.posts-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.5rem;
}

.post-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  display: flex;
  flex-direction: column;
}

.post-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: var(--text-light);
}

.post-card-thumb {
  aspect-ratio: 16 / 9;
  background-color: var(--bg-subtle);
  overflow: hidden;
  position: relative;
}

.post-card-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.post-card:hover .post-card-thumb img {
  transform: scale(1.03);
}

.post-card-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.post-meta-unboxed {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-bottom: 0.625rem;
}

.post-meta-unboxed .tag {
  color: var(--color-primary);
  font-weight: 600;
}

.post-card-title {
  font-size: 1.125rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 0.5rem;
  color: var(--text-main);
}

.post-card-snippet {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.5;
  margin-bottom: 1rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-card-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
  color: var(--text-light);
  border-top: 1px solid var(--border-subtle);
  padding-top: 0.75rem;
}

/* Single Post View */
.single-post-article {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2.25rem 2rem;
}

.post-breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
}

.post-single-title {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  line-height: 1.25;
  color: var(--text-main);
  margin-bottom: 1rem;
  text-wrap: balance;
}

.post-single-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.875rem;
  color: var(--text-muted);
  padding-bottom: 1.25rem;
  margin-bottom: 1.5rem;
  border-bottom: 1px solid var(--border-color);
}

.post-author-chip {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 600;
  color: var(--text-main);
}

.author-chip-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  object-fit: cover;
}

.post-featured-image {
  border-radius: var(--radius-md);
  overflow: hidden;
  margin-bottom: 2rem;
}

/* Table of Contents */
.toc-box {
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  margin: 1.75rem 0;
}

.toc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-main);
  cursor: pointer;
}

.toc-list {
  margin-top: 0.75rem;
  padding-left: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  font-size: 0.9375rem;
}

.toc-list a {
  color: var(--text-muted);
}

.toc-list a:hover {
  color: var(--color-primary);
  text-decoration: underline;
}

/* Post Content Typography */
.post-content {
  font-size: 1.0625rem;
  line-height: 1.8;
  color: var(--text-main);
}

.post-content p {
  margin-bottom: 1.5rem;
}

.post-content h2 {
  font-size: 1.625rem;
  font-weight: 700;
  margin: 2rem 0 1rem;
  letter-spacing: -0.015em;
  border-bottom: 1px solid var(--border-subtle);
  padding-bottom: 0.5rem;
}

.post-content h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 1.5rem 0 0.75rem;
}

.post-content ul, .post-content ol {
  margin: 1rem 0 1.5rem 1.5rem;
}

.post-content li {
  margin-bottom: 0.5rem;
}

.post-content blockquote {
  border-left: 3px solid var(--color-primary);
  padding: 0.75rem 1.25rem;
  background-color: var(--bg-subtle);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  font-style: italic;
  margin: 1.5rem 0;
  color: var(--text-muted);
}

.post-content pre {
  background-color: #0f172a;
  color: #f8fafc;
  padding: 1.25rem;
  border-radius: var(--radius-md);
  overflow-x: auto;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.875rem;
  margin: 1.5rem 0;
  position: relative;
}

.post-content code {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.875em;
  background-color: var(--bg-subtle);
  padding: 0.15em 0.4em;
  border-radius: var(--radius-sm);
  color: var(--color-primary);
}

.post-content pre code {
  background: transparent;
  color: inherit;
  padding: 0;
}

/* Share Buttons */
.share-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 2rem 0;
  padding: 1rem 0;
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
}

.share-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.4rem 0.85rem;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  font-weight: 600;
  color: #ffffff;
  transition: opacity 0.15s ease;
}

.share-btn:hover {
  opacity: 0.9;
  color: #ffffff;
}

.share-btn-x { background-color: #000000; }
.share-btn-fb { background-color: #1877f2; }
.share-btn-wa { background-color: #25d366; }
.share-btn-tg { background-color: #229ed9; }
.share-btn-copy { background-color: #475569; cursor: pointer; }

/* Author Box */
.author-box {
  display: flex;
  gap: 1.25rem;
  padding: 1.5rem;
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  margin: 2rem 0;
}

.author-box-avatar {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.author-box-name {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.25rem;
}

.author-box-bio {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* Sidebar Widgets */
.sidebar-wrapper {
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

.widget {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.25rem;
}

.widget-sticky {
  position: sticky;
  top: calc(var(--header-height) + 1.5rem);
}

.widget-title {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text-main);
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 2px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.widget-title::after {
  content: '';
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--color-primary);
  margin-left: auto;
}

/* Footer */
.site-footer {
  margin-top: auto;
  background-color: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  padding: 2.5rem 0 1.5rem;
}

.footer-container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.footer-top {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 2rem;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--border-subtle);
  padding-top: 1.25rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* Back to Top Button */
#back-to-top {
  position: fixed;
  bottom: 24px;
  right: 24px;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background-color: var(--color-primary);
  color: #ffffff;
  border: none;
  cursor: pointer;
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s ease, visibility 0.2s ease, transform 0.15s ease;
  z-index: 90;
}

#back-to-top.visible {
  opacity: 1;
  visibility: visible;
}

#back-to-top:hover {
  transform: translateY(-3px);
}

/* Toast Notification */
#toast-msg {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background-color: #0f172a;
  color: #ffffff;
  padding: 0.6rem 1.2rem;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  opacity: 0;
  visibility: hidden;
  transition: all 0.2s ease;
  z-index: 10000;
  box-shadow: var(--shadow-lg);
}

#toast-msg.show {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

/* Responsive Media Queries */
@media (max-width: 992px) {
  .main-wrapper {
    grid-template-columns: 1fr;
  }
  .posts-grid {
    grid-template-columns: 1fr;
  }
  .footer-top {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }
  .hamburger-btn {
    display: flex;
  }
  .single-post-article {
    padding: 1.5rem 1.25rem;
  }
  .post-single-title {
    font-size: 1.625rem;
  }
}

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
  var yearEl = document.getElementById('footer-year');
  if (yearEl) yearEl.textContent = new Date().getFullYear();

  var themeToggleBtn = document.getElementById('theme-toggle-btn');
  var savedTheme = localStorage.getItem('theme') || 'light';
  if (savedTheme === 'dark') {
    document.documentElement.setAttribute('data-theme', 'dark');
  }

  if (themeToggleBtn) {
    themeToggleBtn.addEventListener('click', function() {
      var current = document.documentElement.getAttribute('data-theme');
      var target = current === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', target);
      localStorage.setItem('theme', target);
    });
  }

  var hamburgerBtn = document.getElementById('hamburger-btn');
  var mobileDrawer = document.getElementById('mobile-drawer');
  var closeDrawerBtn = document.getElementById('close-drawer-btn');

  if (hamburgerBtn && mobileDrawer) {
    hamburgerBtn.addEventListener('click', function() {
      mobileDrawer.classList.add('active');
    });
  }
  if (closeDrawerBtn && mobileDrawer) {
    closeDrawerBtn.addEventListener('click', function() {
      mobileDrawer.classList.remove('active');
    });
  }
  if (mobileDrawer) {
    mobileDrawer.addEventListener('click', function(e) {
      if (e.target === mobileDrawer) {
        mobileDrawer.classList.remove('active');
      }
    });
  }

  var progressBar = document.getElementById('reading-progress');
  if (progressBar) {
    window.addEventListener('scroll', function() {
      var winScroll = document.documentElement.scrollTop || document.body.scrollTop;
      var height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
      var scrolled = (height > 0) ? (winScroll / height) * 100 : 0;
      progressBar.style.width = scrolled + '%';
    }, { passive: true });
  }

  var backToTopBtn = document.getElementById('back-to-top');
  if (backToTopBtn) {
    window.addEventListener('scroll', function() {
      if (window.scrollY > 400) {
        backToTopBtn.classList.add('visible');
      } else {
        backToTopBtn.classList.remove('visible');
      }
    }, { passive: true });

    backToTopBtn.addEventListener('click', function() {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  var copyBtn = document.getElementById('copy-link-btn');
  var toast = document.getElementById('toast-msg');
  if (copyBtn) {
    copyBtn.addEventListener('click', function() {
      if (navigator.clipboard) {
        navigator.clipboard.writeText(window.location.href).then(function() {
          showToast('Link copied to clipboard!');
        });
      }
    });
  }

  function showToast(text) {
    if (!toast) return;
    toast.textContent = text;
    toast.classList.add('show');
    setTimeout(function() {
      toast.classList.remove('show');
    }, 2500);
  }

  var postBody = document.getElementById('post-body');
  var tocContainer = document.getElementById('toc-container');
  var tocList = document.getElementById('toc-list');
  var tocToggle = document.getElementById('toc-toggle');
  var tocIcon = document.getElementById('toc-icon');

  if (postBody && tocContainer && tocList) {
    var headings = postBody.querySelectorAll('h2, h3');
    if (headings.length >= 2) {
      headings.forEach(function(heading, idx) {
        var id = heading.id || 'section-' + idx;
        heading.id = id;
        var li = document.createElement('li');
        if (heading.tagName.toLowerCase() === 'h3') {
          li.style.marginLeft = '1.25rem';
          li.style.fontSize = '0.875rem';
        }
        var a = document.createElement('a');
        a.href = '#' + id;
        a.textContent = heading.textContent;
        li.appendChild(a);
        tocList.appendChild(li);
      });
      tocContainer.style.display = 'block';

      if (tocToggle && tocIcon) {
        tocToggle.addEventListener('click', function() {
          if (tocList.style.display === 'none') {
            tocList.style.display = 'flex';
            tocIcon.textContent = '[Hide]';
          } else {
            tocList.style.display = 'none';
            tocIcon.textContent = '[Show]';
          }
        });
      }
    }
  }

  if (postBody) {
    var preBlocks = postBody.querySelectorAll('pre');
    preBlocks.forEach(function(pre) {
      var btn = document.createElement('button');
      btn.textContent = 'Copy';
      btn.style.cssText = 'position:absolute; top:8px; right:8px; font-size:11px; padding:3px 8px; border-radius:4px; border:1px solid #334155; background:#1e293b; color:#94a3b8; cursor:pointer; font-family:sans-serif;';
      btn.addEventListener('click', function() {
        var code = pre.querySelector('code') || pre;
        if (navigator.clipboard) {
          navigator.clipboard.writeText(code.innerText).then(function() {
            btn.textContent = 'Copied!';
            btn.style.color = '#38bdf8';
            setTimeout(function() {
              btn.textContent = 'Copy';
              btn.style.color = '#94a3b8';
            }, 2000);
          });
        }
      });
      pre.appendChild(btn);
    });
  }
});
//
